c8-6.solution:
#include <stdio.h>

int count_positive(const int a[], int n) {
    int count = 0;
    for (int i = 0; i < n; i++) { if (a[i] > 0) { count++; } }
    return count;
}

int main(void) {
    int n, a[20];
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 0; i < n; i++) { if (scanf("%d", &a[i]) != 1) { return 1; } }
    printf("%d\n", count_positive(a, n));
    return 0;
}

