c8-8.solution:
#include <stdio.h>

int main(void) {
    int n, a[20];
    if (scanf("%d", &n) != 1) { return 1; }
    for (int i = 0; i < n; i++) { if (scanf("%d", &a[i]) != 1) { return 1; } }
    for (int l = 0, r = n - 1; l < r; l++, r--) { int t = a[l]; a[l] = a[r]; a[r] = t; }
    for (int i = 0; i < n; i++) { printf("%d ", a[i]); }
    printf("\n");
    return 0;
}
